def numeric(t,tape,w):
    """Exact integer/decimal/IEEE rational mathematical fee primitive, not PV."""
    text=t['lexical_form'];dt=(t['datatype_iri'] or '').rsplit('#',1)[-1]
    m=re.fullmatch(r'([+-]?)([0-9]*)(?:\.([0-9]*))?(?:[eE]([+-]?[0-9]+))?',text)
